var t=`1339-chupe-de-camarones`;var n=`world-1339`;var a=`PE`;var o=`south-america`;var s=4;var r=52;var m={en:`Chupe de Camarones`,ua:`Чупе з креветками`};var g={en:`Chupe de Camarones is a dish from Peru featuring yellow onion, garlic, tomato, potato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Чупе з креветками, страва кухні країни Перу з такими основними складниками: жовта цибуля, часник, помідор, картопля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`tomato`,300,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 24 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 24 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:24,i:[[`fish-stock`,900,`ml`],[`potato`,340,`g`],[`sweet-corn`,2,`pcs`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 14 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 14 хвилин до готовності й м’якості.`,t:[`poaching`],m:14,i:[[`shrimp`,680,`g`],[`evaporated-milk`,330,`ml`],[`queso-fresco`,150,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var d={slug:t,id:n,country:`PE`,region:o,servings:4,minutes:52,title:m,text:g,steps:u};export{a as country,d as default,n as id,r as minutes,o as region,s as servings,t as slug,u as steps,g as text,m as title};